"js-access-modal-open\" coords=\"0,0,0,0\" shape=\"rect\" href=\"https://www.sapporo-kokusai.jp/tw/access/\" data-target=\"access-modal11\" />\n<area class=\"js-access-modal-open\" coords=\"0,0,0,0\" shape=\"rect\" href=\"https://www.sapporo-kokusai.jp/tw/access/\" data-target=\"access-modal13\" /></map>\n</div>\n</div>\n</section>\n<div class=\"w7\"></div>\n<h3 id=\"bus\" class=\"section section--pt30 section-img\"><a class=\"btn btn--390\" href=\"https://www.sapporo-kokusai.jp/tw/access/#bussmap\">巴士站點地圖</a></h3>\n<h3 class=\"section section--pt30 section-img\"><a class=\"btn btn--390\" href=\"https://www.access-n.jp/en/\">Resort Liner(reservation bus)English only</a></h3>\n<hr />\n</div></section>\n<section  class='av_textblock_section av-ll94c062-7f702b0585bc44a99a3c3165d70a2113'  itemscope=\"itemscope\" itemtype=\"https://schema.org/BlogPosting\" itemprop=\"blogPost\" ><div class='avia_textblock'  itemprop=\"text\" ><section class=\"section section--pt30\">\n<div class=\"w7\">\n<h3 class=\"section_midashi4 section_midashi4-access\"><span class=\"section_midashi4-access__tag\">從札幌市中心出發約60分鐘</span>從札幌方面前往</h3>\n<div class=\"access-time__img access-time__img--1\">\n<div class=\"svg_box\"><img loading=\"lazy\" decoding=\"async\" class=\"pc\" src=\"https://www.sapporo-kokusai.jp/tw/access/images/images_access4.svg\" alt=\"\" width=\"480\" height=\"82\" /></div>\n</div>\n<div class=\"access-time__img access-time__img--2\">\n<div class=\"svg_box\"><img loading=\"lazy\" decoding=\"async\" class=\"pc\" src=\"https://www.sapporo-kokusai.jp/tw/access/images/images_access5.svg\" alt=\"\" width=\"606\" height=\"80\" /></div>\n</div>\n<h3></h3>\n<h3 class=\"section_midashi4 section_midashi4-access\"><span class=\"section_midashi4-access__tag\">從小樽市中心約40分鐘</span>從小樽方面前往</h3>\n<div class=\"access-time__img access-time__img--3\">\n<div class=\"svg_box\"><img loading=\"lazy\" decoding=\"async\" class=\"pc\" src=\"https://www.sapporo-kokusai.jp/tw/access/images/images_access6.svg\" alt=\"\" width=\"381\" height=\"84\" /></div>\n</div>\n<div class=\"access-time__img access-time__img--4\">\n<div class=\"svg_box\"><img loading=\"lazy\" decoding=\"async\" class=\"pc\" src=\"https://www.sapporo-kokusai.jp/tw/access/images/images_access7.svg\" alt=\"\" width=\"628\" height=\"87\" /></div>\n</div>\n<h3></h3>\n<h3 id=\"chitose\" class=\"section_midashi4 section_midashi4-access\"><span class=\"section_midashi4-access__tag\">從新千歳空港約100鐘</span>從新千歳空港方面前往</h3>\n<div class=\"access-time__img access-time__img--5\">\n<div class=\"svg_box\"><img loading=\"lazy\" decoding=\"async\" class=\"pc\" src=\"https://www.sapporo-kokusai.jp/tw/access/images/images_access8.svg\" alt=\"\" width=\"664\" height=\"84\" /></div>\n</div>\n<div class=\"access-time__img access-time__img--7\">\n<div class=\"svg_box\"><img decoding=\"async\" class=\"pc\" src=\"https://www.sapporo-kokusai.jp/tw/access/images/images_access10.svg\" alt=\"\" /></div>\n</div>\n<div class=\"access-time__img access-time__img--8\">\n<div class=\"svg_box\"><img decoding=\"async\" class=\"pc\" src=\"https://www.sapporo-kokusai.jp/tw/access/images/images_access11.svg\" alt=\"\" /></div>\n</div>\n<p class=\"access__note\">※所需時間可能會因天氣和路況而異。</p>\n</div>\n</section>\n</div></section>\n</div></div>"
